@add("ir02_created_handle_" + fault)
def _(fault=fault):
    facts = supervisor_module.MountFacts("synthetic", "cgroup2", 0, "synthetic", True, "synthetic")
    parent = supervisor_module.DirectoryHandle(50, "owned", 7, 10, facts)
    created = supervisor_module.DirectoryHandle(51, "owned/guard-worker", 7, 11, facts)
    reopened = supervisor_module.DirectoryHandle(52, "owned/guard-worker", 8 if fault == "device" else 7, 12 if fault == "inode" else 11, facts)
    transport = supervisor_module.DescriptorCgroupTransport()
    def fs(fd):
        return SimpleNamespace(st_mode=supervisor_module.stat.S_IFDIR, st_dev=7, st_ino=10 if fd==50 else 11)
    closed=[]
    with ExitStack() as st:
        st.enter_context(mock.patch.object(supervisor_module.os, "mkdir"))
        st.enter_context(mock.patch.object(transport, "_open_child", side_effect=[created,reopened]))
        st.enter_context(mock.patch.object(supervisor_module.os, "fstat", side_effect=fs))
        boundary_stat=st.enter_context(mock.patch.object(supervisor_module.os, "stat", return_value=fs(51)))
        st.enter_context(mock.patch.object(transport, "child_is_populated", return_value=fault=="populated"))
        st.enter_context(mock.patch.object(transport, "list_direct_members", return_value=[]))
        st.enter_context(mock.patch.object(transport, "close_handle", side_effect=lambda h: closed.append(h.fd)))
        removed=st.enter_context(mock.patch.object(supervisor_module.os, "rmdir"))
        owned=transport.create_child(parent,"guard-worker")
        # Creation now captures the new directory identity. This
        # historical control targets the later removal boundary.
        if fault=="stat_error":boundary_stat.side_effect=PermissionError("retained boundary failure")
        if fault=="closed":owned.closed=True
        if fault=="unowned":owned=replace(owned)
        try:transport.remove_empty_child(parent,"guard-worker",owned)
        except (supervisor_module.GuardError,OSError):
            assert fault!="valid";removed.assert_not_called()
        else:assert fault=="valid";removed.assert_called_once_with("guard-worker",dir_fd=50)
        if fault not in {"closed","unowned"}:assert closed==[52]

