@add("ir03_subprocess_"+mode)
def _(mode=mode):
    process=SimpleNamespace(pid=900001,returncode=0)
    if mode in {"timeout","cleanup"}:
        process.communicate=mock.Mock(side_effect=[subprocess.TimeoutExpired(["synthetic"],7,output=b"abc",stderr=b"err"),(b"abcdef",b"error")])
