@add("ne_host_"+command+"_"+mode)
def _(command=command, mode=mode):
    transport = CleanupFaultTransport({command: mode})
    hashes = {name: sha256(HERE/name) for name in host_module.HELPERS}
    outcome = host_module.DockerHostAdapter(transport, HERE, hashes, lambda: "1"*12).run_case("exact_profile")
    assert outcome.status == "failed" and outcome.primary_failure is not None
    assert outcome.ended_at_UTC is not None and outcome.wall_seconds >= 0
    row = next(row for row in outcome.cleanup if row.get("transport_exception"))
    command_row = outcome.commands[row["command_index"]]
    assert command_row["argv"][3] == command and command_row["argv"][-1] == FAKE_ID
    assert row["container_id"] == FAKE_ID and row["result"] is None
    if mode == "launch_failure":
        assert command_row["launch_state"] == "not_started" and command_row["exit_code"] is None
        assert command_row["stdout_base64"] is None
    elif mode == "generic_unknown_transport":
        assert command_row["launch_state"] == "unknown" and command_row["terminal_observed"] is None
    else:
        assert base64.b64decode(command_row["stdout_base64"]) == b"raw\xffprefix"
    if command == "rm":
        assert not outcome.exact_container_removed
    assert any(argv[3] == "rm" for argv, _ in transport.calls)

