@add("ne_io_"+mode+"_and_close_failure")
def _(mode=mode):
    facts = supervisor_module.MountFacts(**GOOD_FACTS)
    directory = supervisor_module.DirectoryHandle(500, "owned", 7, 10, facts)
    transport = supervisor_module.DescriptorCgroupTransport()
    primary = OSError("synthetic I/O failure")
    closing = OSError("synthetic close failure")
    closed = []
    def close(fd):closed.append(fd);raise closing
    reads = ([b"prefix", primary] if mode=="read" else [b"\xff",b""] if mode=="decode" else [b"ok\n",b""])
    writes = [1, primary] if mode=="write" else None
    fake_os = SimpleNamespace(O_RDONLY=os.O_RDONLY, O_WRONLY=os.O_WRONLY, O_NOFOLLOW=os.O_NOFOLLOW,
        open=mock.Mock(return_value=701), close=close,
        read=mock.Mock(side_effect=reads), write=mock.Mock(side_effect=writes) if writes else mock.Mock(side_effect=lambda fd,data:len(data)))
    with mock.patch.object(supervisor_module, "os", fake_os):
        try:
            if mode.startswith("write"):transport.write_text(directory, "memory.max", "7")
            else:transport.read_text(directory, "memory.current")
        except BaseException as error:
            assert closed == [701]
            observations = error.operation_observations
            assert observations["descriptor"]["disposition"] == "unknown"
            if mode=="read":
                assert error is primary and base64.b64decode(observations["received_base64"])==b"prefix"
            elif mode=="decode":
                assert isinstance(error, UnicodeDecodeError)
                assert base64.b64decode(observations["received_base64"])==b"\xff"
            elif mode=="write":
                assert error is primary and observations["confirmed_written_bytes"]==1
                assert base64.b64decode(observations["payload_base64"])==b"7\n"
            else:
                assert error is closing
                assert observations["write_complete" if mode=="write_success" else "decoded_complete"]
            if not mode.endswith("success"):
                assert error.cleanup_failures[0]["code"] == "descriptor_cleanup_failed"
        else:raise AssertionError("close failure was suppressed")

