@add("ne_relative_"+fault)
def _(fault=fault):
    opened, closed = [], []
    descriptors = {}
    primary = OSError("synthetic "+fault)
    secondary = OSError("synthetic secondary close")
    fs_calls = 0
    def open_fd(path, flags, **kwargs):
        fd = 701+len(opened)
        opened.append(fd)
        descriptors[fd] = 10+len(opened)-1
        return fd
    def stat_name(path, **kwargs):
        return SimpleNamespace(st_mode=supervisor_module.stat.S_IFDIR, st_dev=7,
                               st_ino=11 if path=="docker" else 12)
    def fstat(fd):
        nonlocal fs_calls
        fs_calls += 1
        failure_call = {"intermediate_fstat":1,"second_fstat":2,"final_fstat":3}.get(fault)
        if fs_calls==failure_call:raise primary
        return SimpleNamespace(st_mode=supervisor_module.stat.S_IFDIR, st_dev=7, st_ino=descriptors[fd])
    def close(fd):
        closed.append(fd)
        if fault=="old_close" and fd==702:raise primary
        if fault=="final_mount_close" and fd==701:raise primary
        if fault=="mount_verify_close":raise secondary
    verifier = FakeMountVerifier({**GOOD_FACTS,"mount_point":"/synthetic"})
    if fault in ("mount_verify","mount_verify_close"):
        verifier.verify = mock.Mock(side_effect=primary)
    transport = supervisor_module.DescriptorCgroupTransport("/synthetic",verifier,FakeMembership())
    fake_os = SimpleNamespace(O_RDONLY=os.O_RDONLY,O_DIRECTORY=os.O_DIRECTORY,O_NOFOLLOW=os.O_NOFOLLOW,
                              open=open_fd,stat=stat_name,fstat=fstat,close=close)
    with mock.patch.object(supervisor_module,"os",fake_os):
        try:transport._open_relative_dir("docker/"+FAKE_ID)
        except BaseException as error:
            assert error is primary
            assert set(closed)==set(opened)
            assert all(closed.count(fd)==1 for fd in opened)
            observations = error.operation_observations["descriptors"]
            if fault in ("old_close","final_mount_close","mount_verify_close"):
                assert any(row["disposition"]=="unknown" for row in observations)
                assert supervisor_module._descriptor_uncertainty(error)
            else:
                assert all(row["disposition"]=="closed" for row in observations)
            if fault=="old_close":assert opened==[701,702,703] and closed==[702,703,701]
            if fault=="final_fstat":assert closed==[702,701,703]
        else:raise AssertionError("injected traversal failure was suppressed")

