@add("ne_create_"+fault)
def _(fault=fault):
    facts = supervisor_module.MountFacts(**GOOD_FACTS)
    parent = supervisor_module.DirectoryHandle(500,"owned",7,10,facts)
    transport = supervisor_module.DescriptorCgroupTransport()
    primary = OSError("synthetic creation observation failure")
    stat_calls = 0
    closed = []
    def stat_name(*args, **kwargs):
        nonlocal stat_calls
        stat_calls += 1
        if fault=="identity_unobserved":raise primary
        inode = 12 if fault=="replaced" and stat_calls>1 else 11
        return SimpleNamespace(st_mode=supervisor_module.stat.S_IFDIR,st_dev=7,st_ino=inode)
    def close(fd):
        closed.append(fd)
        if fault in ("postopen_close","postopen_rollback_fail"):raise OSError("synthetic close failure")
    removed = mock.Mock(side_effect=OSError("synthetic rollback failure") if fault=="postopen_rollback_fail" else None)
    opened = mock.Mock(return_value=701)
    fake_os = SimpleNamespace(O_RDONLY=os.O_RDONLY,O_DIRECTORY=os.O_DIRECTORY,O_NOFOLLOW=os.O_NOFOLLOW,
        mkdir=mock.Mock(),stat=stat_name,open=opened,fstat=mock.Mock(side_effect=primary),close=close,rmdir=removed)
    with mock.patch.object(supervisor_module,"os",fake_os):
        try:transport.create_child(parent,"guard-worker")
        except BaseException as error:
            assert error is primary and not transport._created_children
            if fault=="identity_unobserved":
                opened.assert_not_called();removed.assert_not_called();assert closed==[]
            else:
                assert closed==[701]
            if fault in ("replaced","identity_unobserved"):
                removed.assert_not_called()
            if fault in ("postopen","postopen_close"):
                removed.assert_called_once_with("guard-worker",dir_fd=500)
                assert error.pending_created_directory["disposition"]=="removed"
            else:
                assert error.pending_created_directory["disposition"]=="unresolved"
            if fault=="postopen_rollback_fail":
                assert {row["code"] for row in error.cleanup_failures} >= {"descriptor_cleanup_failed","cgroup_child_create_rollback_failed"}
            assert supervisor_module._descriptor_uncertainty(error)==(fault!="postopen")
        else:raise AssertionError("creation failure was suppressed")

