@add("ne_bootstrap_interrupted_close_not_retried")
def _():
    facts = supervisor_module.MountFacts(**GOOD_FACTS)
    handles = [supervisor_module.DirectoryHandle(fd,"inherited/"+str(fd),7,fd,facts) for fd in (701,702)]
    primary = InterruptedError("synthetic uncertain interrupted close")
    closed=[]
    def close(fd):
        closed.append(fd)
        if fd==701:raise primary
    fake_os=SimpleNamespace(close=close,setgroups=mock.Mock(),setgid=mock.Mock(),setuid=mock.Mock())
    runtime=supervisor_module.PosixWorkerRuntime(lambda:{},lambda:[],handles,lambda event:None,lambda pid:None,lambda:None)
    with mock.patch.object(supervisor_module,"os",fake_os):
        try:runtime.bootstrap_after_migration()
        except InterruptedError as error:
            assert error is primary and closed==[701,702]
            assert error.operation_observations["privilege_change_started"] is False
            assert handles[0].close_attempted and not handles[0].closed and handles[1].closed
            fake_os.setgroups.assert_not_called();fake_os.setgid.assert_not_called();fake_os.setuid.assert_not_called()
        else:raise AssertionError("interrupted close permitted privilege/bootstrap progress")
